const input = $input.first().json;
// Recover ticket fields from a normal webhook body or legacy nested webhook bodies.
const allowed = ['ticketId','title','description','category','priority','assignedTeam','status','createdAt','aiReason','aiSuggestion','suggestedResponse','deduplication','alert','sla','actor','eventId','updatedAt','source','categoryRationale','aiClassification','priorityReason','assignmentQueue','assignmentReason','assignment','prioritySignals','deduplication','stepTrace'];
const layers = [];
let value = input;
for (let depth = 0; depth < 16; depth++) {
  if (typeof value === 'string') value = JSON.parse(value);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Ticket payload must be a JSON object');
  layers.push(value);
  if (!Object.prototype.hasOwnProperty.call(value, 'body')) break;
  value = value.body;
  if (depth === 15) throw new Error('Webhook body nesting is too deep');
}
const ticket = {};
const trace = [];
for (const layer of layers.reverse()) {
  for (const key of allowed) if (Object.prototype.hasOwnProperty.call(layer, key)) ticket[key] = layer[key];
  if (Array.isArray(layer.workflowTrace)) for (const entry of layer.workflowTrace.slice(-32)) {
    if (typeof entry === 'string' && entry.length <= 80 && !trace.includes(entry)) trace.push(entry);
  }
}
ticket.workflowTrace = trace.slice(-32);
if (JSON.stringify(ticket).length > 65536) throw new Error('Ticket payload exceeds the workflow size limit');
ticket._workflowTime = new Date().toISOString();
return [{ json: ticket }];

const input = $input.first().json;
const ticket = { ...input };
if (typeof ticket.ticketId !== 'string' || !ticket.ticketId.trim() || ticket.ticketId.length > 100) throw new Error('ticketId is required and must be at most 100 characters');
ticket.ticketId = ticket.ticketId.trim();
for (const key of ['title','description','category','priority','status','assignedTeam','aiReason','aiSuggestion','suggestedResponse']) {
  if (ticket[key] !== undefined && typeof ticket[key] !== 'string') throw new Error(key + ' must be a string');
}
if (ticket.title && ticket.title.length > 200) throw new Error('title is too long');
if (ticket.description && ticket.description.length > 10000) throw new Error('description is too long');

for (const key of ['createdAt','updatedAt']) {
 const value = ticket[key];
 if (value != null && ((!['string','number'].includes(typeof value)) || !Number.isFinite(new Date(value).getTime()))) throw new Error(key + ' must be a valid date');
}
return [{ json: ticket }];

const input = $input.first().json;
const snapshot = {};
for (const key of ['ticketId','title','status','category','priority','assignedTeam','createdAt','updatedAt']) if (input[key] !== undefined) snapshot[key] = input[key];
const actor = { type: 'system' };
if (input.actor && typeof input.actor === 'object') {
 for (const key of ['id','name']) if (typeof input.actor[key] === 'string') actor[key] = input.actor[key].slice(0,200);
 if (actor.id) actor.type = 'user';
}
const alert = { required: input.alert?.required === true, sent: input.alert?.sent === true };
const sla = { breached: input.sla?.breached === true };
if (Number.isFinite(input.sla?.targetHours)) sla.targetHours = input.sla.targetHours;
if (typeof input.sla?.dueAt === 'string' && Number.isFinite(new Date(input.sla.dueAt).getTime())) sla.dueAt = new Date(input.sla.dueAt).toISOString();
return [{json:{...input, actor, _auditSnapshot:snapshot, _auditAlert:alert, _auditSla:sla}}];

const input = $input.first().json;
const version = input.updatedAt || input.createdAt || 'unknown';
const eventId = input.eventId ?? ['ticket.processed',input.ticketId,input.status || 'Open',version].join(':');
if (typeof eventId !== 'string' || !eventId.trim() || eventId.length > 300) throw new Error('eventId must be a nonempty string of at most 300 characters');
const auditLog = { event:'ticket.processed', eventId, ticketId:input.ticketId, processedAt:input._workflowTime, actor:input.actor, ticket:input._auditSnapshot, alert:input._auditAlert, sla:input._auditSla, persisted:false };
return [{json:{...input, eventId, auditLog}}];

const input = $input.first().json;
const workflowTrace = [...(input.workflowTrace || [])];
if (!workflowTrace.includes('WF09')) workflowTrace.push('WF09');
return [{json:{...input, workflowTrace, auditLog:{...input.auditLog,workflowTrace}}}];

const input = $input.first().json;
const record = input.auditLog;
if (record.ticketId !== input.ticketId || record.eventId !== input.eventId || !Number.isFinite(new Date(record.processedAt).getTime())) throw new Error('Invalid audit identity or timestamp');
if (!record.workflowTrace.includes('WF09')) throw new Error('Audit trace is incomplete');
return [{json:input}];

const input = $input.first().json;
const ticket = $('07 - Validate Audit Record').first().json;
return [{json:{...ticket,auditLog:{...ticket.auditLog,persisted:true,storageStatus:'stored'}}}];

const input = $input.first().json;
const { _workflowTime, _auditSnapshot, _auditAlert, _auditSla, ...ticket } = input;
return [{json:{...ticket,processingComplete:true,workflowResult:{workflow:'WF09 - Audit Log',ticketId:input.ticketId,processedAt:input.auditLog.processedAt,success:true}}}];
